            C++

    #include <iostream>
using namespace std;

int main()
{

    int i = 5;

    do {
        i++;
        cout << "GFG\n";
    } while (i < 10);

    return 0;
}


            C

    #include <stdio.h>

int main()
{

    int i = 5;

    do {
        printf("GFG\n");
        i++;
    } while (i < 10);

    return 0;
}


            Java

    import java.io.*;

class GFG {
    public static void main(String[] args)
    {

        int i = 5;

        do {
            i++;
            System.out.println("GfG");
        } while (i < 10);
    }
}

